namespace Invoicing;

/// <summary>
/// Creates invoices, computes tax, issues dunning reminders and posts to the ledger.
/// </summary>
public sealed class BillingManager
{
    private readonly InvoicingService _invoicing = new();
    private readonly TaxService _tax = new();
    private readonly DunningService _dunning = new();
    private readonly LedgerService _ledger = new();

    public string CreateInvoice(Invoice invoice, Account account) =>
        _invoicing.CreateInvoice(invoice, account);

    public bool ValidateInvoice(Invoice invoice) =>
        _invoicing.ValidateInvoice(invoice);

    public int IssuedCount => _invoicing.IssuedCount;

    public decimal ComputeTax(Invoice invoice, string countryCode) =>
        _tax.ComputeTax(invoice, countryCode);

    public decimal ResolveRate(string countryCode) =>
        _tax.ResolveRate(countryCode);

    public decimal NetTotal(Invoice invoice) =>
        _tax.NetTotal(invoice);

    public string IssueReminder(Invoice invoice, Account account) =>
        _dunning.IssueReminder(invoice, account);

    public int ReminderLevel(Invoice invoice) =>
        _dunning.ReminderLevel(invoice);

    public void Post(Invoice invoice, decimal amount) =>
        _ledger.Post(invoice, amount);

    public decimal Settle(Invoice invoice, decimal payment) =>
        _ledger.Settle(invoice, payment);

    public decimal ApplyLateFees(Invoice invoice, Account account) =>
        _dunning.ApplyLateFees(invoice, account);

    public string Reconcile(Account account) =>
        _ledger.Reconcile(account);

    public decimal Balance => _ledger.Balance;

    private sealed class InvoicingService
    {
        private readonly List<string> _issuedNumbers = new();
        private int _nextSeq = 1;

        public string CreateInvoice(Invoice invoice, Account account)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                invoice.Number = $"INV-{_nextSeq++:D6}";
            if (_issuedNumbers.Contains(invoice.Number))
                return "duplicate";
            if (invoice.Lines.Count == 0)
                return "empty";
            if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
                return "po required";
            _issuedNumbers.Add(invoice.Number);
            return invoice.Number;
        }

        public bool ValidateInvoice(Invoice invoice)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                return false;
            if (invoice.Lines.Count == 0)
                return false;
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount < 0m)
                    return false;
                if (line.VatRate < 0m || line.VatRate > 1m)
                    return false;
            }
            return true;
        }

        public int IssuedCount => _issuedNumbers.Count;
    }

    private sealed class TaxService
    {
        private readonly Dictionary<string, decimal> _vatRates =
            new(StringComparer.OrdinalIgnoreCase)
            {
                ["GB"] = 0.20m,
                ["DE"] = 0.19m,
                ["FR"] = 0.20m,
            };

        private readonly decimal _reducedRate = 0.05m;

        public decimal ComputeTax(Invoice invoice, string countryCode)
        {
            decimal tax = 0m;
            var rate = ResolveRate(countryCode);
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount <= 0m)
                    continue;
                if (line.VatRate > 0m)
                    tax += line.NetAmount * line.VatRate;
                else if (rate > 0m)
                    tax += line.NetAmount * rate;
            }
            return Math.Round(tax, 2);
        }

        public decimal ResolveRate(string countryCode)
        {
            if (string.IsNullOrEmpty(countryCode))
                return _reducedRate;
            if (_vatRates.TryGetValue(countryCode, out var rate))
                return rate;
            return _reducedRate;
        }

        public decimal NetTotal(Invoice invoice)
        {
            decimal net = 0m;
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount > 0m)
                    net += line.NetAmount;
            }
            return net;
        }
    }

    private sealed class DunningService
    {
        private readonly Dictionary<string, int> _reminderCounts =
            new(StringComparer.Ordinal);

        public string IssueReminder(Invoice invoice, Account account)
        {
            var count = _reminderCounts.TryGetValue(invoice.Number, out var current) ? current : 0;
            if (count >= 3)
                return "escalate";
            if (account.Kind == AccountKind.Government)
                return "no reminder";
            _reminderCounts[invoice.Number] = count + 1;
            if (count == 0)
                return "first notice";
            if (count == 1)
                return "second notice";
            return "final notice";
        }

        public int ReminderLevel(Invoice invoice)
        {
            if (!_reminderCounts.TryGetValue(invoice.Number, out var count))
                return 0;
            if (count > 3)
                return 3;
            return count;
        }

        public decimal ApplyLateFees(Invoice invoice, Account account)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                return 0m;
            var level = _reminderCounts.TryGetValue(invoice.Number, out var count) ? count : 0;
            if (level <= 0)
                return 0m;
            if (account.Kind == AccountKind.Government)
                return 0m;

            decimal fee = 0m;
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount <= 0m)
                    continue;
                fee += line.NetAmount * 0.01m * level;
            }

            if (account.Kind == AccountKind.Business && fee > 100m)
                fee = 100m;
            else if (fee > 50m)
                fee = 50m;
            return Math.Round(fee, 2);
        }
    }

    private sealed class LedgerService
    {
        private readonly List<string> _ledger = new();
        private decimal _balance;

        public void Post(Invoice invoice, decimal amount)
        {
            if (amount == 0m)
                return;
            if (amount > 0m)
                _ledger.Add($"DR {invoice.Number} {amount}");
            else
                _ledger.Add($"CR {invoice.Number} {-amount}");
            _balance += amount;
        }

        public decimal Settle(Invoice invoice, decimal payment)
        {
            if (payment <= 0m)
                return _balance;
            if (string.IsNullOrEmpty(invoice.Number))
                return _balance;
            _ledger.Add($"PMT {invoice.Number} {payment}");
            _balance -= payment;
            if (_balance < 0m)
                _balance = 0m;
            return _balance;
        }

        public string Reconcile(Account account)
        {
            if (string.IsNullOrEmpty(account.Id))
                return "no account";
            if (_ledger.Count == 0)
                return "no entries";

            decimal credits = 0m, debits = 0m;
            foreach (var entry in _ledger)
            {
                if (entry.StartsWith("CR", StringComparison.Ordinal))
                    credits += 1m;
                else if (entry.StartsWith("DR", StringComparison.Ordinal))
                    debits += 1m;
                else if (entry.StartsWith("PMT", StringComparison.Ordinal))
                    credits += 1m;
            }

            if (_balance > 0m && debits > credits)
                return "outstanding";
            if (_balance <= 0m)
                return "settled";
            return "partial";
        }

        public decimal Balance => _balance;
    }
}
